import type { NextRequest } from "next/server";
import { ApiError, assertOk, handle } from "@/lib/api/http";
import { requireUser } from "@/lib/api/session";
import { createClient } from "@/lib/supabase/server";
import { parseLogPatch } from "@/lib/api/schemas";
import { jsonBody, uuid } from "@/lib/api/validate";
import { rowToLog, type LogRow } from "@/lib/api/mappers";

// RouteContext is generated by `next dev` / `next build` — global, no import.
// `params` is a Promise in Next 15+.
export async function PATCH(
  request: NextRequest,
  ctx: RouteContext<"/api/logs/[id]">,
) {
  return handle(async () => {
    const user = await requireUser();
    const id = uuid((await ctx.params).id, "id");
    const patch = parseLogPatch(await jsonBody(request));

    const update: Record<string, unknown> = {};
    if (patch.ts !== undefined) update.smoked_at = new Date(patch.ts).toISOString();
    if (patch.type !== undefined) update.type = patch.type;
    if (patch.trigger !== undefined) update.trigger = patch.trigger;
    if (patch.note !== undefined) update.note = patch.note;

    if (Object.keys(update).length === 0)
      throw new ApiError("Nothing to update.");

    const supabase = await createClient();
    const { data, error } = await supabase
      .from("cigarette_logs")
      .update(update)
      .eq("id", id)
      .eq("user_id", user.id)
      .select()
      .maybeSingle();

    assertOk(error, "Couldn't update that entry.");
    if (!data) throw new ApiError("That entry no longer exists.", 404);

    return { log: rowToLog(data as LogRow) };
  });
}

export async function DELETE(
  _request: NextRequest,
  ctx: RouteContext<"/api/logs/[id]">,
) {
  return handle(async () => {
    const user = await requireUser();
    const id = uuid((await ctx.params).id, "id");

    const supabase = await createClient();
    const { error } = await supabase
      .from("cigarette_logs")
      .delete()
      .eq("id", id)
      .eq("user_id", user.id);

    assertOk(error, "Couldn't delete that entry.");
    // Deliberately not a 404 when the row is already gone: Undo can fire for a
    // log whose create never reached the server, and the outcome is the same.
    return { ok: true };
  });
}
